-- Fresh PostgreSQL schema for the opt-in browser preview.
-- SQLite's schema/migrations remain in database.js. No SQLite database is
-- consulted when this schema is installed. Integer flags preserve app row shapes.
-- SQLite-only search tables and triggers are outside this preview.


CREATE TABLE "account_recovery_codes" (
  "id" BIGINT GENERATED BY DEFAULT AS IDENTITY,
  "user_id" BIGINT NOT NULL,
  "code_hash" TEXT NOT NULL,
  "used" BIGINT DEFAULT 0,
  "created_at" TIMESTAMP(0) WITHOUT TIME ZONE DEFAULT date_trunc('second', CURRENT_TIMESTAMP AT TIME ZONE 'UTC'),
  PRIMARY KEY ("id")
);

CREATE TABLE "attachment_tags" (
  "message_id" BIGINT NOT NULL,
  "rel_path" TEXT NOT NULL,
  "tag_id" BIGINT NOT NULL,
  PRIMARY KEY ("message_id", "rel_path", "tag_id")
);

CREATE TABLE "audit_log" (
  "id" BIGINT GENERATED BY DEFAULT AS IDENTITY,
  "created_at" TIMESTAMP(0) WITHOUT TIME ZONE DEFAULT date_trunc('second', CURRENT_TIMESTAMP AT TIME ZONE 'UTC'),
  "actor_id" BIGINT,
  "actor_username" TEXT,
  "action" TEXT NOT NULL,
  "target_type" TEXT,
  "target_id" BIGINT,
  "target_name" TEXT,
  "details" TEXT DEFAULT NULL,
  PRIMARY KEY ("id")
);

CREATE TABLE "automod_domains" (
  "domain" TEXT,
  "mode" TEXT NOT NULL DEFAULT 'allow',
  "include_subdomains" BIGINT NOT NULL DEFAULT 1,
  "note" TEXT DEFAULT '',
  "added_by" BIGINT,
  "created_at" TIMESTAMP(0) WITHOUT TIME ZONE DEFAULT date_trunc('second', CURRENT_TIMESTAMP AT TIME ZONE 'UTC'),
  PRIMARY KEY ("domain")
);

CREATE TABLE "automod_infractions" (
  "id" BIGINT GENERATED BY DEFAULT AS IDENTITY,
  "user_id" BIGINT,
  "rule" TEXT NOT NULL,
  "channel_id" BIGINT,
  "host" TEXT,
  "excerpt" TEXT DEFAULT '',
  "created_at" TIMESTAMP(0) WITHOUT TIME ZONE DEFAULT date_trunc('second', CURRENT_TIMESTAMP AT TIME ZONE 'UTC'),
  "weight" BIGINT NOT NULL DEFAULT 1,
  PRIMARY KEY ("id")
);

CREATE TABLE "badge_hidden" (
  "user_id" BIGINT NOT NULL,
  "badge_id" BIGINT NOT NULL,
  PRIMARY KEY ("user_id", "badge_id")
);

CREATE TABLE "badge_stats" (
  "user_id" BIGINT,
  "messages" BIGINT NOT NULL DEFAULT 0,
  "forum_likes" BIGINT NOT NULL DEFAULT 0,
  PRIMARY KEY ("user_id")
);

CREATE TABLE "badges" (
  "id" BIGINT GENERATED BY DEFAULT AS IDENTITY,
  "name" TEXT NOT NULL,
  "description" TEXT NOT NULL DEFAULT '',
  "icon_type" TEXT NOT NULL,
  "icon" TEXT NOT NULL,
  "icon_key" TEXT DEFAULT NULL,
  "kind" TEXT NOT NULL,
  "threshold" BIGINT DEFAULT NULL,
  "role_id" BIGINT DEFAULT NULL,
  "enabled" BIGINT NOT NULL DEFAULT 1,
  "position" BIGINT NOT NULL DEFAULT 0,
  "created_by" BIGINT DEFAULT NULL,
  "created_at" TIMESTAMP(0) WITHOUT TIME ZONE DEFAULT date_trunc('second', CURRENT_TIMESTAMP AT TIME ZONE 'UTC'),
  PRIMARY KEY ("id"),
  CHECK (icon_type IN ('emoji', 'image', 'builtin')),
  CHECK (kind IN ('account_age', 'messages', 'forum_likes', 'role', 'manual'))
);

CREATE TABLE "ban_appeals" (
  "id" BIGINT GENERATED BY DEFAULT AS IDENTITY,
  "user_id" BIGINT NOT NULL,
  "appeal" TEXT NOT NULL DEFAULT '',
  "created_at" TIMESTAMP(0) WITHOUT TIME ZONE DEFAULT date_trunc('second', CURRENT_TIMESTAMP AT TIME ZONE 'UTC'),
  PRIMARY KEY ("id")
);

CREATE UNIQUE INDEX "ban_appeals_unique_0" ON "ban_appeals" ("user_id");

CREATE TABLE "bans" (
  "id" BIGINT GENERATED BY DEFAULT AS IDENTITY,
  "user_id" BIGINT NOT NULL,
  "banned_by" BIGINT NOT NULL,
  "reason" TEXT DEFAULT '',
  "created_at" TIMESTAMP(0) WITHOUT TIME ZONE DEFAULT date_trunc('second', CURRENT_TIMESTAMP AT TIME ZONE 'UTC'),
  PRIMARY KEY ("id")
);

CREATE UNIQUE INDEX "bans_unique_1" ON "bans" ("user_id");

CREATE TABLE "bot_commands" (
  "id" BIGINT GENERATED BY DEFAULT AS IDENTITY,
  "webhook_id" BIGINT NOT NULL,
  "command" TEXT NOT NULL,
  "description" TEXT DEFAULT '',
  "subcommands_json" TEXT DEFAULT NULL,
  "created_at" TIMESTAMP(0) WITHOUT TIME ZONE DEFAULT date_trunc('second', CURRENT_TIMESTAMP AT TIME ZONE 'UTC'),
  PRIMARY KEY ("id")
);

CREATE UNIQUE INDEX "bot_commands_unique_2" ON "bot_commands" ("webhook_id", "command");

CREATE TABLE "channel_members" (
  "channel_id" BIGINT,
  "user_id" BIGINT,
  "joined_at" TIMESTAMP(0) WITHOUT TIME ZONE DEFAULT date_trunc('second', CURRENT_TIMESTAMP AT TIME ZONE 'UTC'),
  "auto_all_channels" BIGINT NOT NULL DEFAULT 0,
  "via_role_gate" BIGINT NOT NULL DEFAULT 0,
  PRIMARY KEY ("channel_id", "user_id")
);

CREATE TABLE "channels" (
  "id" BIGINT GENERATED BY DEFAULT AS IDENTITY,
  "name" TEXT NOT NULL,
  "code" TEXT NOT NULL,
  "created_by" BIGINT,
  "created_at" TIMESTAMP(0) WITHOUT TIME ZONE DEFAULT date_trunc('second', CURRENT_TIMESTAMP AT TIME ZONE 'UTC'),
  "show_welcome" BIGINT DEFAULT 0,
  "topic" TEXT DEFAULT '',
  "is_dm" BIGINT DEFAULT 0,
  "code_visibility" TEXT DEFAULT 'public',
  "code_mode" TEXT DEFAULT 'static',
  "code_rotation_type" TEXT DEFAULT 'time',
  "code_rotation_interval" BIGINT DEFAULT 60,
  "code_rotation_counter" BIGINT DEFAULT 0,
  "code_last_rotated" TIMESTAMP(0) WITHOUT TIME ZONE DEFAULT NULL,
  "default_role_id" BIGINT DEFAULT NULL,
  "parent_channel_id" BIGINT DEFAULT NULL,
  "position" BIGINT DEFAULT 0,
  "is_private" BIGINT DEFAULT 0,
  "expires_at" TIMESTAMP(0) WITHOUT TIME ZONE DEFAULT NULL,
  "is_temp_voice" BIGINT DEFAULT 0,
  "streams_enabled" BIGINT DEFAULT 1,
  "music_enabled" BIGINT DEFAULT 1,
  "slow_mode_interval" BIGINT DEFAULT 0,
  "category" TEXT DEFAULT NULL,
  "sort_alphabetical" BIGINT DEFAULT 0,
  "cleanup_exempt" BIGINT DEFAULT 0,
  "channel_type" TEXT DEFAULT 'standard',
  "voice_user_limit" BIGINT DEFAULT 0,
  "media_enabled" BIGINT DEFAULT 1,
  "notification_type" TEXT DEFAULT 'default',
  "voice_enabled" BIGINT DEFAULT 1,
  "text_enabled" BIGINT DEFAULT 1,
  "soundboard_enabled" BIGINT DEFAULT 1,
  "reactions_enabled" BIGINT DEFAULT 1,
  "is_forum" BIGINT DEFAULT 0,
  "forum_tags" TEXT DEFAULT NULL,
  "is_nsfw" BIGINT DEFAULT 0,
  "auto_delete_mode" TEXT DEFAULT 'delete',
  "auto_delete_interval_hours" BIGINT DEFAULT NULL,
  "role_gate" TEXT DEFAULT NULL,
  "forum_layout" TEXT DEFAULT NULL,
  "key_epoch" BIGINT DEFAULT 0,
  "is_group" BIGINT DEFAULT 0,
  "is_self_dm" BIGINT DEFAULT 0,
  "forum_votes" BIGINT DEFAULT 0,
  "forum_blog" BIGINT DEFAULT 0,
  "forum_blog_pics_only" BIGINT DEFAULT 0,
  "discord_channel_id" TEXT DEFAULT NULL,
  "voice_bitrate" BIGINT DEFAULT 0,
  "afk_sub_code" TEXT DEFAULT NULL,
  "afk_timeout_minutes" BIGINT DEFAULT 0,
  "read_only" BIGINT DEFAULT 0,
  "former_names" TEXT DEFAULT NULL,
  PRIMARY KEY ("id")
);

CREATE UNIQUE INDEX "channels_unique_2" ON "channels" ("code");

CREATE TABLE "custom_emojis" (
  "id" BIGINT GENERATED BY DEFAULT AS IDENTITY,
  "name" TEXT NOT NULL,
  "filename" TEXT NOT NULL,
  "uploaded_by" BIGINT,
  "created_at" TIMESTAMP(0) WITHOUT TIME ZONE DEFAULT date_trunc('second', CURRENT_TIMESTAMP AT TIME ZONE 'UTC'),
  PRIMARY KEY ("id")
);

CREATE UNIQUE INDEX "custom_emojis_unique_0" ON "custom_emojis" ("name");

CREATE TABLE "custom_sounds" (
  "id" BIGINT GENERATED BY DEFAULT AS IDENTITY,
  "name" TEXT NOT NULL,
  "filename" TEXT NOT NULL,
  "uploaded_by" BIGINT,
  "created_at" TIMESTAMP(0) WITHOUT TIME ZONE DEFAULT date_trunc('second', CURRENT_TIMESTAMP AT TIME ZONE 'UTC'),
  PRIMARY KEY ("id")
);

CREATE UNIQUE INDEX "custom_sounds_unique_0" ON "custom_sounds" ("name");

CREATE TABLE "deleted_users" (
  "id" BIGINT GENERATED BY DEFAULT AS IDENTITY,
  "username" TEXT NOT NULL,
  "display_name" TEXT DEFAULT NULL,
  "reason" TEXT DEFAULT '',
  "deleted_by" BIGINT,
  "deleted_at" TIMESTAMP(0) WITHOUT TIME ZONE DEFAULT date_trunc('second', CURRENT_TIMESTAMP AT TIME ZONE 'UTC'),
  PRIMARY KEY ("id")
);

CREATE TABLE "disabled_builtin_sounds" (
  "name" TEXT NOT NULL,
  PRIMARY KEY ("name")
);

CREATE TABLE "dm_group_epochs" (
  "channel_id" BIGINT NOT NULL,
  "epoch" BIGINT NOT NULL,
  "published_by" BIGINT NOT NULL,
  "sig" TEXT NOT NULL,
  "roster" TEXT NOT NULL,
  PRIMARY KEY ("channel_id", "epoch")
);

CREATE TABLE "dm_group_invites" (
  "channel_id" BIGINT NOT NULL,
  "user_id" BIGINT NOT NULL,
  "invited_by" BIGINT NOT NULL,
  "created_at" TEXT DEFAULT date_trunc('second', CURRENT_TIMESTAMP AT TIME ZONE 'UTC'),
  PRIMARY KEY ("channel_id", "user_id")
);

CREATE TABLE "dm_group_keys" (
  "channel_id" BIGINT NOT NULL,
  "epoch" BIGINT NOT NULL,
  "recipient_id" BIGINT NOT NULL,
  "wrapped_key" TEXT NOT NULL,
  "wrapped_by" BIGINT NOT NULL,
  "created_at" TEXT DEFAULT date_trunc('second', CURRENT_TIMESTAMP AT TIME ZONE 'UTC'),
  PRIMARY KEY ("channel_id", "epoch", "recipient_id")
);

CREATE TABLE "dm_group_rewrap_requests" (
  "channel_id" BIGINT NOT NULL,
  "epoch" BIGINT NOT NULL,
  "requester_id" BIGINT NOT NULL,
  "created_at" TEXT DEFAULT date_trunc('second', CURRENT_TIMESTAMP AT TIME ZONE 'UTC'),
  PRIMARY KEY ("channel_id", "epoch", "requester_id")
);

CREATE TABLE "eula_acceptances" (
  "id" BIGINT GENERATED BY DEFAULT AS IDENTITY,
  "user_id" BIGINT NOT NULL,
  "version" TEXT NOT NULL,
  "ip_address" TEXT,
  "accepted_at" TIMESTAMP(0) WITHOUT TIME ZONE DEFAULT date_trunc('second', CURRENT_TIMESTAMP AT TIME ZONE 'UTC'),
  "age_verified" BIGINT DEFAULT 0,
  PRIMARY KEY ("id")
);

CREATE UNIQUE INDEX "eula_acceptances_unique_0" ON "eula_acceptances" ("user_id", "version");

CREATE TABLE "fcm_tokens" (
  "id" BIGINT GENERATED BY DEFAULT AS IDENTITY,
  "user_id" BIGINT NOT NULL,
  "token" TEXT NOT NULL,
  "created_at" TIMESTAMP(0) WITHOUT TIME ZONE DEFAULT date_trunc('second', CURRENT_TIMESTAMP AT TIME ZONE 'UTC'),
  "scope" TEXT NOT NULL DEFAULT 'all',
  PRIMARY KEY ("id")
);

CREATE UNIQUE INDEX "fcm_tokens_unique_1" ON "fcm_tokens" ("user_id", "token");

CREATE TABLE "ferry_forum_threads" (
  "id" BIGINT GENERATED BY DEFAULT AS IDENTITY,
  "topic_message_id" BIGINT NOT NULL,
  "channel_id" BIGINT NOT NULL,
  "guild_id" TEXT NOT NULL,
  "discord_forum_id" TEXT NOT NULL,
  "discord_thread_id" TEXT NOT NULL,
  "origin" TEXT NOT NULL DEFAULT 'discord',
  "created_at" TIMESTAMP(0) WITHOUT TIME ZONE DEFAULT date_trunc('second', CURRENT_TIMESTAMP AT TIME ZONE 'UTC'),
  PRIMARY KEY ("id")
);

CREATE UNIQUE INDEX "ferry_forum_threads_unique_1" ON "ferry_forum_threads" ("discord_thread_id", "channel_id");

CREATE UNIQUE INDEX "ferry_forum_threads_unique_2" ON "ferry_forum_threads" ("topic_message_id", "discord_forum_id");

CREATE TABLE "ferry_links" (
  "id" BIGINT GENERATED BY DEFAULT AS IDENTITY,
  "channel_id" BIGINT NOT NULL,
  "guild_id" TEXT NOT NULL,
  "guild_name" TEXT,
  "discord_channel_id" TEXT NOT NULL,
  "discord_channel_name" TEXT,
  "direction" TEXT NOT NULL DEFAULT 'both',
  "out_mode" TEXT NOT NULL DEFAULT 'command',
  "webhook_id" TEXT DEFAULT NULL,
  "webhook_token" TEXT DEFAULT NULL,
  "is_active" BIGINT NOT NULL DEFAULT 1,
  "last_activity_at" TIMESTAMP(0) WITHOUT TIME ZONE DEFAULT NULL,
  "last_error" TEXT DEFAULT NULL,
  "created_by" BIGINT,
  "created_at" TIMESTAMP(0) WITHOUT TIME ZONE DEFAULT date_trunc('second', CURRENT_TIMESTAMP AT TIME ZONE 'UTC'),
  "discord_channel_type" BIGINT DEFAULT NULL,
  PRIMARY KEY ("id")
);

CREATE UNIQUE INDEX "ferry_links_unique_2" ON "ferry_links" ("channel_id", "discord_channel_id");

CREATE TABLE "ferry_message_map" (
  "haven_message_id" BIGINT NOT NULL,
  "discord_message_id" TEXT NOT NULL,
  "discord_channel_id" TEXT NOT NULL,
  "discord_author_id" TEXT DEFAULT NULL,
  "created_at" TIMESTAMP(0) WITHOUT TIME ZONE DEFAULT date_trunc('second', CURRENT_TIMESTAMP AT TIME ZONE 'UTC'),
  PRIMARY KEY ("haven_message_id", "discord_message_id")
);

CREATE TABLE "forum_topic_mutes" (
  "user_id" BIGINT NOT NULL,
  "topic_id" BIGINT NOT NULL,
  PRIMARY KEY ("user_id", "topic_id")
);

CREATE TABLE "forum_votes" (
  "message_id" BIGINT NOT NULL,
  "user_id" BIGINT NOT NULL,
  "value" BIGINT NOT NULL,
  "created_at" TIMESTAMP(0) WITHOUT TIME ZONE DEFAULT date_trunc('second', CURRENT_TIMESTAMP AT TIME ZONE 'UTC'),
  PRIMARY KEY ("message_id", "user_id"),
  CHECK (value IN (1, -1))
);

CREATE TABLE "high_scores" (
  "user_id" BIGINT NOT NULL,
  "game" TEXT NOT NULL,
  "score" BIGINT NOT NULL DEFAULT 0,
  "updated_at" TIMESTAMP(0) WITHOUT TIME ZONE DEFAULT date_trunc('second', CURRENT_TIMESTAMP AT TIME ZONE 'UTC'),
  PRIMARY KEY ("user_id", "game")
);

CREATE TABLE "invite_code_uses" (
  "invite_code_id" BIGINT NOT NULL,
  "user_id" BIGINT NOT NULL,
  "used_at" TIMESTAMP(0) WITHOUT TIME ZONE DEFAULT date_trunc('second', CURRENT_TIMESTAMP AT TIME ZONE 'UTC'),
  PRIMARY KEY ("invite_code_id", "user_id")
);

CREATE TABLE "invite_codes" (
  "id" BIGINT GENERATED BY DEFAULT AS IDENTITY,
  "code" TEXT NOT NULL,
  "label" TEXT DEFAULT '',
  "channels" TEXT DEFAULT '',
  "enabled" BIGINT DEFAULT 1,
  "max_uses" BIGINT DEFAULT 0,
  "expires_at" TIMESTAMP(0) WITHOUT TIME ZONE DEFAULT NULL,
  "created_by" BIGINT,
  "created_at" TIMESTAMP(0) WITHOUT TIME ZONE DEFAULT date_trunc('second', CURRENT_TIMESTAMP AT TIME ZONE 'UTC'),
  "spent" BIGINT DEFAULT 0,
  PRIMARY KEY ("id")
);

CREATE UNIQUE INDEX "invite_codes_unique_0" ON "invite_codes" ("code");

CREATE TABLE "ip_bans" (
  "ip" TEXT,
  "banned_by" BIGINT,
  "reason" TEXT DEFAULT '',
  "created_at" TIMESTAMP(0) WITHOUT TIME ZONE DEFAULT date_trunc('second', CURRENT_TIMESTAMP AT TIME ZONE 'UTC'),
  PRIMARY KEY ("ip")
);

CREATE TABLE "listening_tokens" (
  "user_id" BIGINT,
  "token" TEXT NOT NULL,
  "created_at" TIMESTAMP(0) WITHOUT TIME ZONE DEFAULT date_trunc('second', CURRENT_TIMESTAMP AT TIME ZONE 'UTC'),
  PRIMARY KEY ("user_id")
);

CREATE UNIQUE INDEX "listening_tokens_unique_1" ON "listening_tokens" ("token");

CREATE TABLE "media_objects" (
  "rel_path" TEXT,
  "bytes" BIGINT NOT NULL,
  "content_type" TEXT,
  "state" TEXT NOT NULL DEFAULT 'live',
  "created_at" TIMESTAMP(0) WITHOUT TIME ZONE DEFAULT date_trunc('second', CURRENT_TIMESTAMP AT TIME ZONE 'UTC'),
  "deleted_at" TIMESTAMP(0) WITHOUT TIME ZONE,
  PRIMARY KEY ("rel_path")
);

CREATE TABLE "message_highlights" (
  "message_id" BIGINT,
  "role_id" BIGINT,
  "user_id" BIGINT NOT NULL,
  "created_at" TIMESTAMP(0) WITHOUT TIME ZONE DEFAULT date_trunc('second', CURRENT_TIMESTAMP AT TIME ZONE 'UTC'),
  PRIMARY KEY ("message_id")
);

CREATE TABLE "message_quotes" (
  "message_id" BIGINT,
  "quote_of" BIGINT NOT NULL,
  PRIMARY KEY ("message_id")
);

CREATE TABLE "messages" (
  "id" BIGINT GENERATED BY DEFAULT AS IDENTITY,
  "channel_id" BIGINT,
  "user_id" BIGINT,
  "content" TEXT NOT NULL,
  "reply_to" BIGINT,
  "created_at" TIMESTAMP(0) WITHOUT TIME ZONE DEFAULT date_trunc('second', CURRENT_TIMESTAMP AT TIME ZONE 'UTC'),
  "edited_at" TIMESTAMP(0) WITHOUT TIME ZONE DEFAULT NULL,
  "burn_seconds" BIGINT DEFAULT 0,
  "burning_started_at" TIMESTAMP(0) WITHOUT TIME ZONE DEFAULT NULL,
  "break_chain" BIGINT DEFAULT 0,
  "type" TEXT DEFAULT 'user',
  "original_name" TEXT DEFAULT NULL,
  "is_webhook" BIGINT DEFAULT 0,
  "webhook_username" TEXT DEFAULT NULL,
  "webhook_id" BIGINT DEFAULT NULL,
  "persona_id" BIGINT DEFAULT NULL,
  "persona_username" TEXT DEFAULT NULL,
  "ferry_target" TEXT DEFAULT NULL,
  "persona_avatar" TEXT DEFAULT NULL,
  "blog_comment" BIGINT DEFAULT 0,
  "nsfw_by" BIGINT DEFAULT NULL,
  "imported_from" TEXT DEFAULT NULL,
  "webhook_avatar" TEXT DEFAULT NULL,
  "discord_message_id" TEXT DEFAULT NULL,
  "is_archived" BIGINT DEFAULT 0,
  "poll_data" TEXT DEFAULT NULL,
  "thread_id" BIGINT DEFAULT NULL,
  "title" TEXT DEFAULT NULL,
  "tags" TEXT DEFAULT NULL,
  "closed" BIGINT DEFAULT 0,
  "nsfw" BIGINT DEFAULT 0,
  "e2e_files" TEXT DEFAULT NULL,
  "destruct_at" TEXT DEFAULT NULL,
  "silent" BIGINT NOT NULL DEFAULT 0,
  PRIMARY KEY ("id")
);

CREATE TABLE "mod_cases" (
  "id" BIGINT GENERATED BY DEFAULT AS IDENTITY,
  "user_id" BIGINT NOT NULL,
  "actor_id" BIGINT,
  "actor_name" TEXT,
  "type" TEXT NOT NULL,
  "reason" TEXT,
  "severity" BIGINT NOT NULL DEFAULT 0,
  "duration_minutes" BIGINT,
  "created_at" TIMESTAMP(0) WITHOUT TIME ZONE DEFAULT date_trunc('second', CURRENT_TIMESTAMP AT TIME ZONE 'UTC'),
  "seen_at" TIMESTAMP(0) WITHOUT TIME ZONE,
  "revoked_at" TIMESTAMP(0) WITHOUT TIME ZONE,
  "revoked_by" TEXT,
  PRIMARY KEY ("id")
);

CREATE TABLE "mutes" (
  "id" BIGINT GENERATED BY DEFAULT AS IDENTITY,
  "user_id" BIGINT NOT NULL,
  "muted_by" BIGINT NOT NULL,
  "reason" TEXT DEFAULT '',
  "expires_at" TIMESTAMP(0) WITHOUT TIME ZONE NOT NULL,
  "created_at" TIMESTAMP(0) WITHOUT TIME ZONE DEFAULT date_trunc('second', CURRENT_TIMESTAMP AT TIME ZONE 'UTC'),
  PRIMARY KEY ("id")
);

CREATE TABLE "pinned_messages" (
  "id" BIGINT GENERATED BY DEFAULT AS IDENTITY,
  "message_id" BIGINT NOT NULL,
  "channel_id" BIGINT NOT NULL,
  "pinned_by" BIGINT NOT NULL,
  "pinned_at" TIMESTAMP(0) WITHOUT TIME ZONE DEFAULT date_trunc('second', CURRENT_TIMESTAMP AT TIME ZONE 'UTC'),
  PRIMARY KEY ("id")
);

CREATE UNIQUE INDEX "pinned_messages_unique_1" ON "pinned_messages" ("message_id");

CREATE TABLE "poll_votes" (
  "id" BIGINT GENERATED BY DEFAULT AS IDENTITY,
  "message_id" BIGINT NOT NULL,
  "user_id" BIGINT NOT NULL,
  "option_index" BIGINT NOT NULL,
  "created_at" TIMESTAMP(0) WITHOUT TIME ZONE DEFAULT date_trunc('second', CURRENT_TIMESTAMP AT TIME ZONE 'UTC'),
  PRIMARY KEY ("id")
);

CREATE UNIQUE INDEX "poll_votes_unique_1" ON "poll_votes" ("message_id", "user_id", "option_index");

CREATE TABLE "push_subscriptions" (
  "id" BIGINT GENERATED BY DEFAULT AS IDENTITY,
  "user_id" BIGINT NOT NULL,
  "endpoint" TEXT NOT NULL,
  "p256dh" TEXT NOT NULL,
  "auth" TEXT NOT NULL,
  "created_at" TIMESTAMP(0) WITHOUT TIME ZONE DEFAULT date_trunc('second', CURRENT_TIMESTAMP AT TIME ZONE 'UTC'),
  "scope" TEXT NOT NULL DEFAULT 'all',
  PRIMARY KEY ("id")
);

CREATE UNIQUE INDEX "push_subscriptions_unique_1" ON "push_subscriptions" ("user_id", "endpoint");

CREATE TABLE "reactions" (
  "id" BIGINT GENERATED BY DEFAULT AS IDENTITY,
  "message_id" BIGINT NOT NULL,
  "user_id" BIGINT NOT NULL,
  "emoji" TEXT NOT NULL,
  "created_at" TIMESTAMP(0) WITHOUT TIME ZONE DEFAULT date_trunc('second', CURRENT_TIMESTAMP AT TIME ZONE 'UTC'),
  PRIMARY KEY ("id")
);

CREATE UNIQUE INDEX "reactions_unique_1" ON "reactions" ("message_id", "user_id", "emoji");

CREATE TABLE "read_positions" (
  "user_id" BIGINT NOT NULL,
  "channel_id" BIGINT NOT NULL,
  "last_read_message_id" BIGINT NOT NULL DEFAULT 0,
  PRIMARY KEY ("user_id", "channel_id")
);

CREATE TABLE "released_uploads" (
  "rel_path" TEXT,
  "released_at" TIMESTAMP(0) WITHOUT TIME ZONE DEFAULT date_trunc('second', CURRENT_TIMESTAMP AT TIME ZONE 'UTC'),
  PRIMARY KEY ("rel_path")
);

CREATE TABLE "role_channel_access" (
  "role_id" BIGINT NOT NULL,
  "channel_id" BIGINT NOT NULL,
  "grant_on_promote" BIGINT NOT NULL DEFAULT 0,
  "revoke_on_demote" BIGINT NOT NULL DEFAULT 0,
  PRIMARY KEY ("role_id", "channel_id")
);

CREATE TABLE "role_menus" (
  "message_id" BIGINT,
  "channel_id" BIGINT NOT NULL,
  "created_by" BIGINT,
  "title" TEXT DEFAULT '',
  "data" TEXT NOT NULL,
  "created_at" TIMESTAMP(0) WITHOUT TIME ZONE DEFAULT date_trunc('second', CURRENT_TIMESTAMP AT TIME ZONE 'UTC'),
  PRIMARY KEY ("message_id")
);

CREATE TABLE "role_permissions" (
  "role_id" BIGINT NOT NULL,
  "permission" TEXT NOT NULL,
  "allowed" BIGINT NOT NULL DEFAULT 1,
  PRIMARY KEY ("role_id", "permission")
);

CREATE TABLE "roles" (
  "id" BIGINT GENERATED BY DEFAULT AS IDENTITY,
  "name" TEXT NOT NULL,
  "level" BIGINT NOT NULL DEFAULT 0,
  "scope" TEXT NOT NULL DEFAULT 'server',
  "color" TEXT DEFAULT NULL,
  "auto_assign" BIGINT NOT NULL DEFAULT 0,
  "created_at" TIMESTAMP(0) WITHOUT TIME ZONE DEFAULT date_trunc('second', CURRENT_TIMESTAMP AT TIME ZONE 'UTC'),
  "link_channel_access" BIGINT NOT NULL DEFAULT 0,
  "icon" TEXT DEFAULT NULL,
  "max_upload_mb" BIGINT DEFAULT NULL,
  "transparent" BIGINT NOT NULL DEFAULT 0,
  "mentionable" BIGINT NOT NULL DEFAULT 1,
  "show_on_profile" BIGINT NOT NULL DEFAULT 1,
  "color2" TEXT DEFAULT NULL,
  "color_shimmer" BIGINT NOT NULL DEFAULT 0,
  PRIMARY KEY ("id")
);

CREATE TABLE "scheduled_messages" (
  "id" BIGINT GENERATED BY DEFAULT AS IDENTITY,
  "user_id" BIGINT NOT NULL,
  "channel_id" BIGINT NOT NULL,
  "content" TEXT NOT NULL,
  "send_at" TEXT NOT NULL,
  "created_at" TIMESTAMP(0) WITHOUT TIME ZONE DEFAULT date_trunc('second', CURRENT_TIMESTAMP AT TIME ZONE 'UTC'),
  PRIMARY KEY ("id")
);

CREATE TABLE "server_settings" (
  "key" TEXT,
  "value" TEXT NOT NULL,
  PRIMARY KEY ("key")
);

CREATE TABLE "sound_preferences" (
  "id" BIGINT GENERATED BY DEFAULT AS IDENTITY,
  "user_id" BIGINT NOT NULL,
  "sound_name" TEXT NOT NULL,
  "hidden" BIGINT DEFAULT 0,
  "custom_order" BIGINT DEFAULT NULL,
  PRIMARY KEY ("id")
);

CREATE UNIQUE INDEX "sound_preferences_unique_1" ON "sound_preferences" ("user_id", "sound_name");

CREATE TABLE "sound_volumes" (
  "sound_name" TEXT NOT NULL,
  "volume" BIGINT NOT NULL DEFAULT 100,
  PRIMARY KEY ("sound_name")
);

CREATE TABLE "stickers" (
  "id" BIGINT GENERATED BY DEFAULT AS IDENTITY,
  "name" TEXT NOT NULL,
  "pack_name" TEXT NOT NULL DEFAULT 'General',
  "filename" TEXT NOT NULL,
  "uploaded_by" BIGINT,
  "created_at" TIMESTAMP(0) WITHOUT TIME ZONE DEFAULT date_trunc('second', CURRENT_TIMESTAMP AT TIME ZONE 'UTC'),
  PRIMARY KEY ("id")
);

CREATE UNIQUE INDEX "stickers_unique_0" ON "stickers" ("name");

CREATE TABLE "thread_reads" (
  "user_id" BIGINT NOT NULL,
  "thread_id" BIGINT NOT NULL,
  "last_read_reply_id" BIGINT NOT NULL DEFAULT 0,
  PRIMARY KEY ("user_id", "thread_id")
);

CREATE TABLE "totp_backup_codes" (
  "id" BIGINT GENERATED BY DEFAULT AS IDENTITY,
  "user_id" BIGINT NOT NULL,
  "code_hash" TEXT NOT NULL,
  "used" BIGINT DEFAULT 0,
  "created_at" TIMESTAMP(0) WITHOUT TIME ZONE DEFAULT date_trunc('second', CURRENT_TIMESTAMP AT TIME ZONE 'UTC'),
  PRIMARY KEY ("id")
);

CREATE TABLE "upload_ownership" (
  "rel_path" TEXT,
  "user_id" BIGINT,
  "bytes" BIGINT NOT NULL DEFAULT 0,
  "scope" TEXT NOT NULL DEFAULT 'channel',
